<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
class Product extends Model { use SoftDeletes; protected $fillable=['category_id','subcategory_id','name','slug','sku','short_description','description','material','price','compare_price','cost_price','stock','low_stock_threshold','weight','colors','sizes','tags','rating','review_count','is_active','is_featured','is_new','is_bestseller','is_limited','meta_title','meta_description','canonical_url']; protected $casts=['price'=>'decimal:2','compare_price'=>'decimal:2','cost_price'=>'decimal:2','colors'=>'array','sizes'=>'array','tags'=>'array','is_active'=>'boolean','is_featured'=>'boolean','is_new'=>'boolean','is_bestseller'=>'boolean','is_limited'=>'boolean']; public function category(){return $this->belongsTo(Category::class);} public function subcategory(){return $this->belongsTo(Category::class,'subcategory_id');} public function images(){return $this->hasMany(ProductImage::class)->orderBy('sort_order');} public function primaryImage(){return $this->hasOne(ProductImage::class)->where('is_primary',true)->withDefault(['path'=>'images/placeholder.webp']);} public function variants(){return $this->hasMany(ProductVariant::class);} public function collections(){return $this->belongsToMany(Collection::class)->withPivot('sort_order');} public function reviews(){return $this->hasMany(Review::class);} public function approvedReviews(){return $this->reviews()->where('status','approved');} public function scopeActive($q){return $q->where('is_active',true);} public function scopeSearch($q,$term){return $q->when($term,fn($q)=>$q->where(fn($x)=>$x->where('name','like',"%{$term}%")->orWhere('sku','like',"%{$term}%")->orWhere('material','like',"%{$term}%")));} public function getRouteKeyName(){return 'slug';} public function getDiscountPercentAttribute(){return $this->compare_price>$this->price?round((($this->compare_price-$this->price)/$this->compare_price)*100):0;} public function getImageUrlAttribute(){return asset($this->primaryImage->path);} }
